from itertools import permutations

def find_all_interval_series(n):
    for perm in permutations(range(n)):
        diffs = [abs(perm[i+1] - perm[i]) for i in range(n-1)]
        if sorted(diffs) == list(range(1, n)):
            return list(perm)
    return None

result = find_all_interval_series(3)
print(f"Solution: {result}")

# Verify
if result:
    diffs = [abs(result[i+1] - result[i]) for i in range(len(result)-1)]
    print(f"Permutation: {result}")
    print(f"Differences: {diffs}")
    print(f"Sorted diffs: {sorted(diffs)}")
    print(f"Expected: {list(range(1, 3))}")
